import{z as o,x as s,o as A,c as p,q as B,j as i,D as t,d as E,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"黑盒优化器在组合里的使用","description":"","frontmatter":{"title":"黑盒优化器在组合里的使用","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-blackbox-optimizers.md","filePath":"quant/pf-blackbox-optimizers.md","lastUpdated":1791063341000}'),C={name:"quant/pf-blackbox-optimizers.md"};function d(h,a,u,m,f,c){const r=s("Mermaid");return A(),p("div",null,[a[2]||(a[2]=B('<h1 id="黑盒优化器在组合里的使用" tabindex="-1">黑盒优化器在组合里的使用 <a class="header-anchor" href="#黑盒优化器在组合里的使用" aria-label="Permalink to &quot;黑盒优化器在组合里的使用&quot;">​</a></h1><div class="epigraph"><p>梯度是优化器的坦白书：没有它，每一次「更优」都只是一次未经检验的声明。</p><footer>—— 据 Hansen and Ostermeier, Evolutionary Computation, 2001（CMA-ES）；Jones, Schonlau and Welch, Journal of Global Optimization, 1998 整理</footer></div><p><a href="/quant/pf-regularized">上一课</a>把不信任写进目标函数：\\(\\ell_1\\)、\\(\\ell_2\\)、收缩与约束当正则，全部在凸的世界里兑现。缺口在边界之外：最多持有五十只（基数约束）、手数取整、固定佣金台阶、必须用历史情景原样计算的路径目标——这些把问题推出凸集，<a href="/quant/cvar-opt">CVaR 优化</a>的线性规划也救不了带整数与台阶的版本。梯度缺席，本课写黑盒优化器在组合里的用法与纪律：什么时候值得用、怎么验收、怎么不被它过拟合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>黑盒指只能查询输入输出、拿不到导数的优化器：遗传算法、模拟退火、CMA-ES、贝叶斯优化。<span class="marginnote">「黑盒」就是只许喂参数、只报分数、看不到内部导数的优化器。直觉类比：凸优化像带着等高线地图和坡度表登山，每一步都知道哪边更陡；黑盒则像蒙眼下山谷找最低点，只能反复试「往这边挪一分，海拔升了还是降了」。</span>组合语境的诱惑特别大，因为目标函数现成——就是回测器。把回测器当适应度函数去搜权重，等价于把多重检验机器接在权重空间的每一根轴上。错法清单：把搜出的参数当发现；种子一换结果大变，报告的却是单一最好的那一次；两千次评估的搜索史被忘掉，<a href="/quant/harvey-liu-zhu">Harvey-Liu-Zhu 多重检验</a>的折价没有记进任何台账；以及更隐蔽的——凸化其实可行，只是写约束的人懒得想。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是给黑盒搜索立一套先于运行的纪律：能凸化的外围全部凸化，把搜索空间缩到真正非凸的核；评估预算与种子方案在开跑前钉死，跑完不追加；验收只认多种子的解分布与凸基线的间隙，搜索次数按多重检验口径折价入账。三件套的顺序不可换：先缩空间，再谈预算，最后谈验收。</p><h3 id="纪律三件套" tabindex="-1">纪律三件套 <a class="header-anchor" href="#纪律三件套" aria-label="Permalink to &quot;纪律三件套&quot;">​</a></h3><p>第一件，先凸化再黑盒。基数用 \\(\\ell_1\\) 松弛加投影，或连续解取整后做局部修复；固定成本拆成两阶段（先定持仓、再定交易批次）；路径类目标若能写成情景上的凸形式就退回上一课。凸化把搜索空间缩小一寸，过拟合的表面积就小一寸——只有真正凸不动的核才交给黑盒。第二件，管理评估预算。组合黑盒的每次评估都是一次回测，昂贵且缓慢；贝叶斯优化用代理模型与采集函数挑下一次评估的点（Jones 等 1998 的高效全局优化是原型），CMA-ES 适合中等维度的连续核，遗传算法对付离散与混合变量。<span class="marginnote">「代理模型」就是用便宜的猜想来代替昂贵的真跑：先用少量真实回测拟合一个近似曲面，再让采集函数猜「哪个点最值得下一次真跑」。数字实例：预算 500 次回测，贝叶斯优化可能花 30 次建代理、470 次挑点，省下的既是算力，也是会被记进台账的检验次数。</span>预算要事先钉死，跑完不许追加——追加预算就是追加检验次数。第三件，验收协议。报告多种子的解分布而不是单点；与凸松弛解比较，得到最优性间隙的经验感受；搜索次数进台账，按 <a href="/quant/deflated-sharpe">Deflated Sharpe</a> 与<a href="/quant/backtest-overfitting">过拟合次数与试错</a>的口径折价。</p>',9)),(A(),i(n,null,{default:t(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E7%BB%84%E5%90%88%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20CVX%7B%22%E5%8F%AF%E5%87%B8%E5%8C%96%EF%BC%9F%22%7D%0A%20%20CVX%20--%3E%7C%E6%98%AF%7C%20QP%5B%22%E6%AD%A3%E5%88%99%E5%8C%96%E4%B8%8E%E5%87%B8%E6%B1%82%E8%A7%A3%EF%BC%9A%E4%B8%8A%E4%B8%80%E8%AF%BE%22%5D%0A%20%20CVX%20--%3E%7C%E5%90%A6%7C%20PRE%5B%22%E5%85%88%E5%87%B8%E5%8C%96%E5%A4%96%E5%9B%B4%EF%BC%9A%E6%9D%BE%E5%BC%9B%E3%80%81%E5%8F%96%E6%95%B4%E3%80%81%E4%B8%A4%E9%98%B6%E6%AE%B5%22%5D%0A%20%20PRE%20--%3E%20BB%5B%22%E9%BB%91%E7%9B%92%E6%A0%B8%EF%BC%9ACMA-ES%20%E6%88%96%E8%B4%9D%E5%8F%B6%E6%96%AF%E4%BC%98%E5%8C%96%22%5D%0A%20%20BB%20--%3E%20ACC%5B%22%E5%A4%9A%E7%A7%8D%E5%AD%90%E5%88%86%E5%B8%83%E4%B8%8E%E5%87%B8%E5%9F%BA%E7%BA%BF%20gap%22%5D%0A%20%20ACC%20--%3E%20LED%5B%22%E6%8A%98%E4%BB%B7%E5%8F%B0%E8%B4%A6%EF%BC%9A%E6%90%9C%E7%B4%A2%E6%AC%A1%E6%95%B0%E5%85%A5%E8%B4%A6%22%5D%0A%20%20LED%20--%3E%20OUT%5B%22%E5%8F%AF%E5%A4%8D%E7%8E%B0%E7%9A%84%E5%8F%82%E6%95%B0%E4%B8%8E%E8%A7%A3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("黑盒在组合里比在超参里更危险，原因在评估数据的重复使用：调学习率的搜索消耗的是验证集的一次机会，组合黑盒却常在同一个历史窗口里反复评估——验证信息被成千次透支，样本内最优与样本外表现的相关性随评估次数衰减，"),e("a",{href:"/quant/pbo"},"Probability of Backtest Overfitting"),E(" 与 "),e("a",{href:"/quant/cscv"},"CSCV 组合对称交叉验证"),E("正是给这类搜索做尸检的工具。种子敏感性与上一课的平坦谷底同源：非凸目标的多解集合比凸问题大得多，种子决定停在哪一个坑里；报告单点解等于把一片解集伪装成唯一真值。为什么贝叶斯优化值得优先考虑：代理模型显式携带不确定性，采集函数在「利用已知好区」与「探索未知区」之间做权衡，评估次数省下的同时，每一步选择都有记录可审计——这对台账纪律是加分而不是负担。")],-1)),(A(),i(n,null,{default:t(()=>[l(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8E%86%E5%8F%B2%E7%AA%97%E5%8F%A3%E5%9B%BA%E5%AE%9A%E4%B8%8D%E5%8F%98%22%5D%20--%3E%20E%5B%22%E6%AF%8F%E6%AC%A1%E8%AF%84%E4%BC%B0%E6%9D%83%E9%87%8D%20%3D%20%E8%B7%91%E4%B8%80%E6%AC%A1%E5%9B%9E%E6%B5%8B%22%5D%0A%20%20E%20--%3E%20R%5B%22%E8%AF%84%E4%BC%B0%E4%B8%8A%E5%8D%83%E6%AC%A1%EF%BC%9A%E9%AA%8C%E8%AF%81%E4%BF%A1%E6%81%AF%E8%A2%AB%E5%8F%8D%E5%A4%8D%E9%80%8F%E6%94%AF%22%5D%0A%20%20R%20--%3E%20F%5B%22%E6%A0%B7%E6%9C%AC%E5%86%85%E6%9C%80%E4%BC%98%E8%A7%A3%E9%80%90%E6%B8%90%E5%AF%B9%E9%BD%90%E5%99%AA%E5%A3%B0%22%5D%0A%20%20F%20--%3E%20D%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%E8%A1%A8%E7%8E%B0%E9%9A%8F%E8%AF%84%E4%BC%B0%E6%AC%A1%E6%95%B0%E8%A1%B0%E5%87%8F%22%5D%0A%20%20D%20--%3E%20T%5B%22%E6%8C%89%E6%90%9C%E7%B4%A2%E6%AC%A1%E6%95%B0%E6%8A%98%E4%BB%B7%E9%87%8D%E7%AE%97%E6%98%BE%E8%91%97%E6%80%A7%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">「种子」是随机算法的起点编号。常见误区：只报告种子里运气最好的那一次。实际上换十颗种子得到十个不同的解，说明目标函数坑多、单点解不可信；把十次结果的分布（均值与区间）写进报告，才算对读者诚实。</span></p><p><span class="marginnote">台账口径：一次两千次评估的黑盒搜索，等价于对「这套框架能赚钱」做了两千次隐式检验；报告的 \\(t\\) 统计量要按搜索次数重算，折价后的显著性才是可以拿去投委会的数字。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写具体算法的实现细节：CMA-ES 的自适应协方差、采集函数的族谱各有专文；执行层母单拆分与日内路径是 <a href="/quant/almgren-chriss">Almgren-Chriss</a> 课序的对象，与这里的仓位层黑盒分属两层。黑盒不是凸优化的替代品：凸可得时用黑盒是纪律问题，不是能力问题；它也不是过拟合的豁免——恰恰相反，搜索越自由，<a href="/quant/white-reality-check">White Reality Check</a> 这类数据挖掘校正越必要。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>黑盒只在没有梯度可用的核上使用：基数、取整、固定成本、路径目标；外围先凸化，缩小搜索空间。</li><li>评估预算事先钉死；贝叶斯优化用代理省评估，CMA-ES 适合连续核。</li><li>验收靠多种子分布与凸基线间隙，不靠单一最好解；种子敏感性提示多解集合很大。</li><li>搜索次数进多重检验台账，按折价口径重算显著性。</li><li>出处：Hansen &amp; Ostermeier, <em>Evolutionary Computation</em>, 2001；Jones, Schonlau &amp; Welch, <em>Journal of Global Optimization</em>, 1998；折价口径据 backtest-overfitting 一课整理。</li></ul>',6))])}const b=o(C,[["render",d]]);export{F as __pageData,b as default};
